const Search={index:null,async buildIndex(){this.index={customers:[],appointments:[],orders:[]};const o=await DB.db.customers.toArray();this.index.customers=o.map(e=>{var r,s,t;return{id:e.id,type:"customer",title:`${e.firstName} ${e.lastName}`,subtitle:e.address?`${e.address.line1}, ${e.address.postcodeFormatted}`:"",phone:e.phone,customerNumber:e.customerNumber,keywords:[e.firstName,e.lastName,e.phone,e.email,e.customerNumber,(r=e.address)==null?void 0:r.line1,(s=e.address)==null?void 0:s.postcode,(t=e.address)==null?void 0:t.city].filter(Boolean).join(" ").toLowerCase()}});const a=await DB.db.appointments.toArray();this.index.appointments=a.map(e=>({id:e.id,type:"appointment",title:`${Utils.formatDate(e.date,"short")} ${Utils.formatTime(e.date)}`,subtitle:e.type,keywords:[e.type,e.status,e.outcome,Utils.formatDate(e.date)].filter(Boolean).join(" ").toLowerCase()}));const i=await DB.db.orders.toArray();this.index.orders=i.map(e=>({id:e.id,type:"order",title:e.orderNumber,subtitle:e.supplierOrderNumber||"",keywords:[e.orderNumber,e.supplierOrderNumber,e.status].filter(Boolean).join(" ").toLowerCase()}))},async search(o,a={}){var r;if(!o||o.trim().length<2)return[];const i=o.toLowerCase().trim(),e=[];if(!a.types||a.types.includes("customer"))try{const s=await DB.searchCustomers(i);e.push(...s.map(t=>({type:"customer",id:t.id,title:`${t.firstName} ${t.lastName}`,subtitle:t.customerNumber,detail:t.address?`${t.address.line1}${t.address.postcode?", "+t.address.postcode:""}`:"",icon:"person",data:t})))}catch(s){console.error("Customer search failed:",s)}if(!a.types||a.types.includes("appointment"))try{const s=await DB.db.appointments.filter(t=>{var n;return e.find(m=>m.type==="customer"&&m.id===t.customerId)||((n=t.notes)==null?void 0:n.toLowerCase().includes(i))}).limit(10).toArray();for(const t of s){const d=await DB.db.customers.get(t.customerId);e.push({type:"appointment",id:t.id,title:`${Utils.formatDate(t.date,"short")} \u2014 ${Utils.formatTime(t.date)}`,subtitle:d?`${d.firstName} ${d.lastName}`:"Unknown",detail:((r=CONFIG.appointmentTypes.find(n=>n.id===t.type))==null?void 0:r.name)||t.type,icon:"event",data:t})}}catch(s){console.error("Appointment search failed:",s)}if(!a.types||a.types.includes("order"))try{const s=await DB.db.orders.filter(t=>(t.orderNumber||"").toLowerCase().startsWith(i)||(t.supplierOrderNumber||"").toLowerCase().startsWith(i)).limit(10).toArray();for(const t of s){const d=await DB.db.customers.get(t.customerId);e.push({type:"order",id:t.id,title:t.orderNumber,subtitle:d?`${d.firstName} ${d.lastName}`:"Unknown",detail:`\xA3${t.total}`,icon:"receipt",data:t})}}catch(s){console.error("Order search failed:",s)}return e.slice(0,a.limit||20)},async searchByPostcode(o){const a=Utils.normalizePostcode(o);return await DB.db.customers.where("postcodeNormalized").startsWith(a).limit(20).toArray()},async searchNearby(o,a,i=10){return(await DB.db.customers.toArray()).filter(r=>{var t;return(t=r.address)!=null&&t.latLng?Geo.calculateDistance(o,a,r.address.latLng[0],r.address.latLng[1])<=i:!1}).map(r=>({...r,distance:Geo.calculateDistance(o,a,r.address.latLng[0],r.address.latLng[1])})).sort((r,s)=>r.distance-s.distance)}};
